using System;using System.Reflection;using System.Threading.Tasks;using UnityEngine;using UnityEditor;
public static class LegacyDesignReference {public static async Task<string> Show(string page){var g=UnityEngine.Object.FindAnyObjectByType<ForgeMvp>();var f=BindingFlags.NonPublic|BindingFlags.Instance;typeof(ForgeMvp).GetField("progressLoaded",f).SetValue(g,false);typeof(ForgeMvp).GetField("showTitle",f).SetValue(g,false);typeof(ForgeMvp).GetMethod("StopMouseTrace",f).Invoke(g,null);typeof(ForgeMvp).GetMethod("ResetProgressForDebug",f).Invoke(g,new object[]{false});if(g.HierarchyGame)g.HierarchyGame.gameObject.SetActive(false);g.SetHierarchyGame(null);if(page=="guide")typeof(ForgeMvp).GetField("showGuideBook",f).SetValue(g,true);await Task.Delay(300);return "Legacy IMGUI reference: "+page;}}
